import{_ as r,c as a,o as t,a5 as i}from"./chunks/framework.DuCYAsAJ.js";const g=JSON.parse('{"title":"认证与会话管理","description":"","frontmatter":{"title":"认证与会话管理","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#2.1","branch":"main","level":1,"order":2.1},"headers":[],"relativePath":"posts/projects/zfeed/02-front-api-gateway/01-authentication-and-session-management.md","filePath":"posts/projects/zfeed/02-front-api-gateway/01-authentication-and-session-management.md","lastUpdated":1779632679000}'),o={name:"posts/projects/zfeed/02-front-api-gateway/01-authentication-and-session-management.md"};function n(l,e,s,d,p,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="认证与会话管理" tabindex="-1">认证与会话管理 <a class="header-anchor" href="#认证与会话管理" aria-label="Permalink to &quot;认证与会话管理&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/front.go" target="_blank" rel="noreferrer">app/front/front.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/config/config.go" target="_blank" rel="noreferrer">app/front/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/logoutlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/logoutlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/redis_lua.go" target="_blank" rel="noreferrer">app/front/internal/middleware/redis_lua.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/sessionauth.go" target="_blank" rel="noreferrer">app/front/internal/middleware/sessionauth.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/sessionauth_test.go" target="_blank" rel="noreferrer">app/front/internal/middleware/sessionauth_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/userloginstatusauthmiddleware.go" target="_blank" rel="noreferrer">app/front/internal/middleware/userloginstatusauthmiddleware.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/verify_and_renew_session.lua" target="_blank" rel="noreferrer">app/front/internal/middleware/verify_and_renew_session.lua</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/batchgetuserlogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/batchgetuserlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/getmelogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/getmelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/getuserlogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/getuserlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/getuserprofilelogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/getuserprofilelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/logoutlogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/logoutlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/errorx/error.go" target="_blank" rel="noreferrer">pkg/errorx/error.go</a></li></ul></details><p>本文说明 <code>zfeed</code> 系统中的用户认证与会话管理实现。整体架构依赖 Bearer token 流程、Redis 会话存储，以及用于保证会话校验和 TTL（Time-To-Live）续期原子性的 Lua 脚本。</p><h2 id="会话生命周期概览" tabindex="-1">会话生命周期概览 <a class="header-anchor" href="#会话生命周期概览" aria-label="Permalink to &quot;会话生命周期概览&quot;">​</a></h2><p>用户通过 <code>user-rpc</code> 服务成功登录或注册后，会创建会话。会话创建后，请求在进入下游业务逻辑之前，会先由 <code>front-api</code> 网关中的自定义中间件完成校验。</p><h3 id="会话存储结构" tabindex="-1">会话存储结构 <a class="header-anchor" href="#会话存储结构" aria-label="Permalink to &quot;会话存储结构&quot;">​</a></h3><p>会话以双 key 映射形式存储在 Redis 中，同时支持 token 到用户的查找，以及用户到 token 的管理（例如单设备登录或全局登出）。</p><table tabindex="0"><thead><tr><th>Key 模式</th><th>用途</th><th>值</th></tr></thead><tbody><tr><td><code>user:session:{token}</code></td><td>校验指定会话 token</td><td><code>userId</code></td></tr><tr><td><code>user:session:user:{userId}</code></td><td>将用户映射到当前活跃 token</td><td><code>token</code></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/sessionauth.go#L20-L21" target="_blank" rel="noreferrer">app/front/internal/middleware/sessionauth.go#20-21</a></p><hr><h2 id="认证流程" tabindex="-1">认证流程 <a class="header-anchor" href="#认证流程" aria-label="Permalink to &quot;认证流程&quot;">​</a></h2><p>系统使用标准的 <code>Authorization: Bearer &lt;token&gt;</code> 请求头。<code>front-api</code> 网关主要通过两个中间件处理认证：<code>UserLoginStatusAuthMiddleware</code> 和 <code>OptionalLoginMiddleware</code>。</p><h3 id="token-提取" tabindex="-1">Token 提取 <a class="header-anchor" href="#token-提取" aria-label="Permalink to &quot;Token 提取&quot;">​</a></h3><p><code>middleware</code> 中的 <code>extractToken</code> 函数同时处理标准 Bearer 请求头和原始 token 字符串，以保持向后兼容。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/sessionauth.go#L34-L50" target="_blank" rel="noreferrer">app/front/internal/middleware/sessionauth.go#34-50</a></p><h3 id="校验与原子续期" tabindex="-1">校验与原子续期 <a class="header-anchor" href="#校验与原子续期" aria-label="Permalink to &quot;校验与原子续期&quot;">​</a></h3><p>为了减少 Redis 往返次数并避免竞态条件，会话校验和 TTL 延长通过 Lua 脚本（<code>verify_and_renew_session.lua</code>）一次性完成。</p><ol><li>检查 token：脚本取出给定 token 关联的 <code>userId</code>。</li><li>校验一致性：检查 <code>user:session:user:{userId}</code> key 是否仍然指向当前 token，确保该会话没有被新登录顶替。</li><li>续期逻辑：如果剩余 TTL 小于特定阈值（由 <code>renewRatio</code> 定义），则两个 key 都会被延长到完整的 <code>defaultSessionTTL</code>。</li></ol><h4 id="会话续期参数" tabindex="-1">会话续期参数 <a class="header-anchor" href="#会话续期参数" aria-label="Permalink to &quot;会话续期参数&quot;">​</a></h4><ul><li>默认 TTL：7 天（<code>7 * 24 * time.Hour</code>）。</li><li>续期比例：1/3。当会话剩余生命周期小于总 TTL 的 1/3 时触发续期（7 天会话约为 2.3 天）。</li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/sessionauth.go#L23-L25" target="_blank" rel="noreferrer">app/front/internal/middleware/sessionauth.go#23-25</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/sessionauth.go#L52-L92" target="_blank" rel="noreferrer">app/front/internal/middleware/sessionauth.go#52-92</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/verify_and_renew_session.lua#L1-L21" target="_blank" rel="noreferrer">app/front/internal/middleware/verify_and_renew_session.lua#1-21</a></p><h3 id="中间件组件" tabindex="-1">中间件组件 <a class="header-anchor" href="#中间件组件" aria-label="Permalink to &quot;中间件组件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>逻辑</th></tr></thead><tbody><tr><td><code>UserLoginStatusAuthMiddleware</code></td><td>强制校验。token 缺失或无效时，返回 <code>401 Unauthorized</code> 错误。</td></tr><tr><td><code>OptionalLoginMiddleware</code></td><td>宽松校验。若存在有效 token，则把 <code>user_id</code> 注入上下文；否则继续执行，不注入上下文。</td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/sessionauth_test.go#L145-L257" target="_blank" rel="noreferrer">app/front/internal/middleware/sessionauth_test.go#145-257</a></p><hr><h2 id="代码实体空间映射" tabindex="-1">代码实体空间映射 <a class="header-anchor" href="#代码实体空间映射" aria-label="Permalink to &quot;代码实体空间映射&quot;">​</a></h2><p>下列图示将“认证”这一自然语言概念映射到 <code>zfeed</code> 仓库中的具体代码实体。</p><h3 id="会话校验序列" tabindex="-1">会话校验序列 <a class="header-anchor" href="#会话校验序列" aria-label="Permalink to &quot;会话校验序列&quot;">​</a></h3><p>该图展示 <code>front-api</code> 中间件如何通过 Lua 脚本与 Redis 交互。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/sessionauth.go#L67-L91" target="_blank" rel="noreferrer">app/front/internal/middleware/sessionauth.go#67-91</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/verify_and_renew_session.lua#L3-L20" target="_blank" rel="noreferrer">app/front/internal/middleware/verify_and_renew_session.lua#3-20</a></p><h3 id="登出实现" tabindex="-1">登出实现 <a class="header-anchor" href="#登出实现" aria-label="Permalink to &quot;登出实现&quot;">​</a></h3><p>登出流程会通过 <code>user-rpc</code> 服务确保 Redis 中的会话数据被清除。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/logoutlogic.go#L32-L53" target="_blank" rel="noreferrer">app/front/internal/logic/user/logoutlogic.go#32-53</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/logoutlogic.go#L28-L38" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/logoutlogic.go#28-38</a></p><hr><h2 id="会话校验逻辑详解" tabindex="-1">会话校验逻辑详解 <a class="header-anchor" href="#会话校验逻辑详解" aria-label="Permalink to &quot;会话校验逻辑详解&quot;">​</a></h2><p><code>verifyAndRenewSession</code> 函数是校验逻辑的核心。它会基于配置的 <code>SessionTTL</code> 计算续期阈值。</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// From app/front/internal/middleware/sessionauth.go</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">threshold </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ttlSeconds) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> renewRatio)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tokenKey </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> redisTokenKeyPrefix </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;:&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> token</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resp, err </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rds.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EvalCtx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, VerifyAndRenewSessionScript, []</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{tokenKey}, token, redisUserKeyPrefix, ttlSeconds, threshold)</span></span></code></pre></div><p>Lua 脚本确保只有 token 到用户、用户到 token 两个映射保持同步时，会话才被视为有效：</p><ol><li><code>userId = GET user:session:{token}</code></li><li><code>storedToken = GET user:session:user:{userId}</code></li><li><code>if storedToken != token then return &quot;&quot;</code></li></ol><p>这可以防止“幽灵会话”：旧 token 仍然存在于 Redis 中，但实际上已被同一用户的新登录会话替换。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/sessionauth.go#L61-L67" target="_blank" rel="noreferrer">app/front/internal/middleware/sessionauth.go#61-67</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/verify_and_renew_session.lua#L3-L12" target="_blank" rel="noreferrer">app/front/internal/middleware/verify_and_renew_session.lua#3-12</a></p><hr><h2 id="错误处理" tabindex="-1">错误处理 <a class="header-anchor" href="#错误处理" aria-label="Permalink to &quot;错误处理&quot;">​</a></h2><p>认证错误使用 <code>pkg/errorx</code> 包，确保整个 API 返回一致的 HTTP 状态码。</p><ul><li>缺少 token：返回 <code>errorx.NewUnauthorized(&quot;用户未登录&quot;)</code>，映射到 HTTP 401。</li><li>token 无效或过期：返回 <code>errorx.NewUnauthorized(&quot;用户未登录&quot;)</code>。</li><li>上下文缺少 UserID：如果业务逻辑需要用户 ID，但中间件未提供，则返回 <code>errorx.NewUnauthorized(&quot;用户未登录&quot;)</code>。</li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/sessionauth.go#L54-L91" target="_blank" rel="noreferrer">app/front/internal/middleware/sessionauth.go#54-91</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/logoutlogic.go#L33-L36" target="_blank" rel="noreferrer">app/front/internal/logic/user/logoutlogic.go#33-36</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/errorx/error.go#L1-L50" target="_blank" rel="noreferrer">pkg/errorx/error.go#1-50</a></p>`,46)])])}const u=r(o,[["render",n]]);export{g as __pageData,u as default};
